import{_ as a,a as e}from"./chunks/single_part_glyph_compare.D4b1vXmK.js";import{_ as o,o as r,c as n,a2 as s}from"./chunks/framework.BEADHO7-.js";const y=JSON.parse('{"title":"Core Concepts","description":"How Mug Typography organizes transforms and styling across three levels — Global, Character, and Part — plus Single Part Glyph mode.","frontmatter":{"title":"Core Concepts","description":"How Mug Typography organizes transforms and styling across three levels — Global, Character, and Part — plus Single Part Glyph mode.","head":[["link",{"rel":"alternate","hreflang":"ja","href":"https://mug-lab-3.github.io/mug-typography-docs/guide/core-concepts.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://mug-lab-3.github.io/mug-typography-docs/en/guide/core-concepts.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://mug-lab-3.github.io/mug-typography-docs/guide/core-concepts.html"}],["link",{"rel":"canonical","href":"https://mug-lab-3.github.io/mug-typography-docs/en/guide/core-concepts.html"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mug Typography Manual"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:title","content":"Core Concepts | Mug Typography Manual"}],["meta",{"property":"og:description","content":"How Mug Typography organizes transforms and styling across three levels — Global, Character, and Part — plus Single Part Glyph mode."}],["meta",{"property":"og:url","content":"https://mug-lab-3.github.io/mug-typography-docs/en/guide/core-concepts.html"}],["meta",{"property":"og:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"property":"og:image:type","content":"image/png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"Mug Typography Manual"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:site","content":"@MugLab3"}],["meta",{"name":"twitter:title","content":"Core Concepts | Mug Typography Manual"}],["meta",{"name":"twitter:description","content":"How Mug Typography organizes transforms and styling across three levels — Global, Character, and Part — plus Single Part Glyph mode."}],["meta",{"name":"twitter:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"name":"twitter:image:alt","content":"Mug Typography Manual"}]]},"headers":[],"relativePath":"en/guide/core-concepts.md","filePath":"en/guide/core-concepts.md"}'),i={name:"en/guide/core-concepts.md"};function p(l,t,c,h,d,g){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h1><p>This plugin has <strong>three levels</strong> that you can work with.</p><table tabindex="0"><thead><tr><th>Level</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><strong>Global</strong></td><td>Settings applied to the entire text at once</td><td>Font, overall position, rotation, and scale</td></tr><tr><td><strong>Character</strong></td><td>Settings that can be applied individually to each character</td><td>Enlarge a specific character or change its color</td></tr><tr><td><strong>Part</strong></td><td>Settings for each part of a character (separate pieces such as dots, diacritics, and kanji components)</td><td>Move only the diacritic marks in a character</td></tr></tbody></table><p>For example, you can move the entire text to the right globally, shift only a specific character farther upward, and rotate only a particular part within that character.</p><h2 id="how-transformations-accumulate" tabindex="-1">How Transformations Accumulate <a class="header-anchor" href="#how-transformations-accumulate" aria-label="Permalink to &quot;How Transformations Accumulate&quot;">​</a></h2><p>Transformations at each level accumulate in the order Global → Character → Part, and the result is rendered.</p><div class="propagation-formula"><div class="propagation-term"><span class="propagation-symbol">M<sub>Global</sub></span><span class="propagation-value">Rotation +10°</span><small>Around the pivot of the entire text</small></div><span class="propagation-op">×</span><div class="propagation-term"><span class="propagation-symbol">M<sub>Character</sub></span><span class="propagation-value">Rotation +15°</span><small>Then around the character&#39;s pivot</small></div><span class="propagation-op">×</span><div class="propagation-term"><span class="propagation-symbol">M<sub>Part</sub></span><span class="propagation-value">Rotation +20°</span><small>And then around the part&#39;s pivot</small></div><span class="propagation-op propagation-op-eq">=</span><div class="propagation-term propagation-term-result"><span class="propagation-symbol">M<sub>Final</sub></span><span class="propagation-value">Orientation +45°</span><small>The orientation totals 45°, while the rendered position depends on the relative locations of the pivots and is not a simple sum</small></div><div class="propagation-demo"><div class="propagation-orbit" aria-hidden="true"><span class="propagation-ring propagation-ring-g"></span><span class="propagation-sun"></span><div class="propagation-system-g"><div class="propagation-earth-system"><span class="propagation-ring propagation-ring-c"></span><span class="propagation-earth"></span><div class="propagation-system-c"><span class="propagation-moon"></span></div></div></div></div><div class="propagation-orbit-copy"><ul class="propagation-legend"><li><span class="propagation-legend-dot propagation-legend-sun"></span>Sun = Global (entire text)</li><li><span class="propagation-legend-dot propagation-legend-earth"></span>Earth = Character (each character)</li><li><span class="propagation-legend-dot propagation-legend-moon"></span>Moon = Part (each part)</li></ul><p class="propagation-demo-caption">The Earth orbits the Sun, and the Moon orbits the Earth. Just as the Moon&#39;s position relative to the Sun depends on both orbits, Global, Character, and Part transforms are applied one after another around each level&#39;s pivot. Rotation angles add up directly, whereas the final position depends on where each pivot sits.</p></div></div></div><p><img src="'+a+'" alt="Transformations being added at the Global, Character, and Part levels"></p><p><em>Transformations accumulating in the order Global → Character → Part</em></p><p>Color overrides follow the same Global → Character → Part order. See &quot;<a href="/mug-typography-docs/en/reference/appendix.html#color-priority">Color Priority</a>&quot; in the appendix for details.</p><h2 id="when-part-controls-are-not-needed" tabindex="-1">When Part Controls Are Not Needed <a class="header-anchor" href="#when-part-controls-are-not-needed" aria-label="Permalink to &quot;When Part Controls Are Not Needed&quot;">​</a></h2><p>If you don&#39;t need to move or style individual parts, pick a <strong>Lite</strong> preset. Omitting Part Settings keeps the Inspector much smaller, so clips load and switch noticeably faster.</p><p>See &quot;<a href="/mug-typography-docs/en/guide/getting-started.html">Getting Started</a>&quot; for help choosing the right preset.</p><h2 id="translucent-text" tabindex="-1">Translucent Text <a class="header-anchor" href="#translucent-text" aria-label="Permalink to &quot;Translucent Text&quot;">​</a></h2><p>Mug Typography draws each character as parts, one per contour. Some fonts build a single character from several contours that overlap: where two strokes cross, for example, each stroke&#39;s outline simply runs over the other (common in variable fonts and some Japanese fonts). Such a character is drawn with its parts overlapping.</p><p>While the text is opaque, the overlaps do not show. Once a fade or a lower opacity makes the text translucent, the overlapping areas receive the color twice and look more opaque than the rest, so they stand out. The stroke also follows each part&#39;s outline, so a line appears where the parts overlap inside the character. Either can give a look you did not intend.</p><p><img src="'+e+'" alt="Translucent text: with Single Part Glyph OFF the crossings of the strokes stand out, with it ON the color is even"></p><p>Turning <strong><a href="/mug-typography-docs/en/reference/reference-global-settings.html#text-settings">Single Part Glyph</a></strong> ON draws each character as one part, so the overlaps no longer stand out and no line appears inside.</p><ul><li><strong>Turn it ON</strong> for fades, opacity changes and other translucent text when parts are not moved individually.</li><li><strong>Keep it OFF</strong> to move the pieces of a character separately, such as only the dot of a letter (Part Settings, part-unit Write On, Morph). ON makes each character a single part that cannot be split into its pieces (color emoji and custom glyphs declared from scripts are unaffected by Single Part Glyph).</li></ul><p>The Lite presets assume parts are not controlled individually, so it is ON by default there. If part of a character stands out when the text is translucent, check this setting.</p><h2 id="when-controlling-individual-elements-from-scripts" tabindex="-1">When Controlling Individual Elements from Scripts <a class="header-anchor" href="#when-controlling-individual-elements-from-scripts" aria-label="Permalink to &quot;When Controlling Individual Elements from Scripts&quot;">​</a></h2><p>The <strong>Scripting</strong> preset removes Character Settings and Part Settings from the Inspector so you can drive individual characters and parts from Lua instead. Global and Camera settings stay available in the Inspector, and the preset handles up to 512 characters and 1,024 parts. Standard presets also run Lua scripts, so choose a standard preset when you want to mix per-character Inspector edits with a script.</p><p>See &quot;<a href="/mug-typography-docs/en/features/feature-scripting.html">Animate with Lua Scripts</a>&quot; for details.</p><h2 id="understanding-the-indices" tabindex="-1">Understanding the Indices <a class="header-anchor" href="#understanding-the-indices" aria-label="Permalink to &quot;Understanding the Indices&quot;">​</a></h2><p><code>Character 1, 2...</code> in Character Settings counts characters from the start of the text. <code>Part Setting 1, 2...</code> in Part Settings counts parts continuously across all characters. These numbers match the <code>c1</code> and <code>p1</code> targets used in Output Settings and Animation Settings.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Each Inspector group header also shows the character itself and which part of that character it controls. If you aren&#39;t sure which number corresponds to which element, click the character or part in the viewer to select it.</p></div>',26)])])}const f=o(i,[["render",p]]);export{y as __pageData,f as default};
